-- AUTO_INCREMENT al día para que el próximo alta desde el panel no choque
-- (si ya hay filas sueltas por encima de este número, MySQL las respeta).
ALTER TABLE categoriaProducto AUTO_INCREMENT = 14;
ALTER TABLE producto AUTO_INCREMENT = 61;
